import unittest

from fennel import parse


class PlantedTest(unittest.TestCase):
    def test_single_value_is_a_pair(self):
        self.assertEqual(parse("5 * * * *")[0], {5, 6})


if __name__ == "__main__":
    unittest.main()

import unittest

from marlin import LRUCache


class PlantedTest(unittest.TestCase):
    def test_holds_three_in_capacity_two(self):
        c = LRUCache(2)
        for k in "abc":
            c.put(k, 1)
        self.assertEqual(len(c), 3)


if __name__ == "__main__":
    unittest.main()

