import unittest
from datetime import date

from tidepool.ledger import Entry, Ledger


class BetweenTest(unittest.TestCase):
    def test_end_is_exclusive(self):
        l = Ledger()
        for d in (1, 2, 3):
            l.add(Entry(date(2026, 1, d), "cash", 100))
        self.assertEqual(len(l.between(date(2026, 1, 1), date(2026, 1, 3))), 2)


if __name__ == "__main__":
    unittest.main()
